style.css:
@-moz-document domain("youtube.com") {
/* General Background - Black with Navy Blue Tint */
    body {
        background-color: #0d0d19 !important;
    }

    /* Top Navigation Bar */
    #masthead-container {
        background-color: #12122c !important;
        box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5) !important;
    }

    /* Search Bar */
    #search-form input {
        background: #0a0a23 !important;
        border: 2px solid #1a1a5e !important;
        color: white !important;
        border-radius: 25px !important;
        padding: 8px 15px !important;
        transition: 0.3s ease-in-out !important;
    }

    #search-form input:focus {
        border-color: #3a3aff !important;
        box-shadow: 0 0 10px #3a3aff !important;
    }

    /* Search Button */
    ytd-searchbox button {
        background: #1a1a5e !important;
        border-radius: 50% !important;
        padding: 8px !important;
        transition: 0.3s ease-in-out !important;
    }

    ytd-searchbox button:hover {
        background: #3a3aff !important;
        box-shadow: 0 0 10px #3a3aff !important;
    }

    /* Video Thumbnails */
    .ytd-thumbnail {
        transition: 0.3s ease-in-out !important;
    }

    .ytd-thumbnail:hover {
        filter: brightness(0.8) !important;
    }

    /* Buttons */
    ytd-button-renderer.style-scope {
        background: #1a1a5e !important;
        color: white !important;
        border-radius: 8px !important;
        transition: 0.3s ease-in-out !important;
    }

    ytd-button-renderer.style-scope:hover {
        background: #3a3aff !important;
        box-shadow: 0 0 10px #3a3aff !important;
    }

    /* Hide YouTube Default Loading Bar */
    yt-page-navigation-progress {
        display: none !important;
    }
}
